package com.yeyamo_mobile.api.partner_service.application;
import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Component;import com.yeyamo_mobile.api.partner_service.application.port.KycPolicy;import com.yeyamo_mobile.api.partner_service.domain.model.*;
@Component public class DefaultKycPolicy implements KycPolicy{public void validate(Partner p,List<PartnerDocument>docs){Set<DocumentType>types=docs.stream().map(PartnerDocument::documentType).collect(java.util.stream.Collectors.toSet());if(!types.contains(DocumentType.OWNER_IDENTITY))throw new PartnerException("KYC_DOCUMENT_MISSING","La pièce d'identité du responsable est obligatoire",HttpStatus.BAD_REQUEST);if(p.getBusinessType()==BusinessType.COMPANY&&!types.contains(DocumentType.BUSINESS_REGISTRATION))throw new PartnerException("KYC_DOCUMENT_MISSING","Le registre de commerce est obligatoire",HttpStatus.BAD_REQUEST);}}
